def text(x):
    if x is None:
        return ''
    if isinstance(x, (list, tuple, set)):
        return ' '.join([text(i) for i in x])
    if isinstance(x, dict):
        return ' '.join([text(k) + ' ' + text(v) for k, v in x.items()])
    return str(x).lower()

def needverb(tt):
    if 'cool' in tt:
        return 'cool'
    if 'heat' in tt:
        return 'heat'
    if 'clean' in tt:
        return 'clean'
    return ''

def hook(ctx, nb):
    tt = text(getv(ctx, 'task.task_type', ''))
    target = text(getv(ctx, 'task.target_type', ''))
    dest = text(getv(ctx, 'task.destination_type', ''))
    verb = needverb(tt)
    if not verb:
        nb['transformed'] = True
    else:
        nb['transformed'] = False
    act = text(getv(ctx, 'action.final_action', getv(ctx, 'action.normalized', getv(ctx, 'action.raw', ''))))
    obs = text(ctx.get('observation', ''))
    inv = text(getv(ctx, 'world.inventory', ''))
    pc = getv(ctx, 'world.placed_count', nb.get('placed_count', 0))
    try:
        pc = int(pc)
    except Exception:
        pc = 0
    if pc > nb.get('placed_count', 0):
        nb['placed_count'] = pc
    locs = getv(ctx, 'world.placed_locations', [])
    if isinstance(locs, str):
        locs = [locs]
    if isinstance(locs, (list, tuple, set)):
        locs = [text(x) for x in locs if x]
    if act.startswith('put ') and target and target in act and 'you put' in obs:
        if not dest or dest in act:
            nb['placed_count'] = max(nb.get('placed_count', 0), 1)
            loc = ''
            if ' in/on ' in act:
                loc = act.split(' in/on ', 1)[1]
            if loc and loc not in nb.get('placed_locations', []):
                nb['placed_locations'] = nb.get('placed_locations', []) + [loc]
    if act.startswith('take ') and target and target in act and 'you pick up' in obs:
        if dest and dest in act and nb.get('placed_count', 0) > 0:
            nb['placed_count'] = max(0, nb.get('placed_count', 0) - 1)
    if verb and target and act.startswith(verb + ' ') and target in act and 'nothing happens' not in obs:
        nb['transformed'] = True
    carrying = bool(target and target in inv and 'not carrying' not in inv and 'nothing' not in inv)
    wrong = bool(inv and 'nothing' not in inv and 'not carrying' not in inv and target and target not in inv)
    take_ok = bool(target and any(a.startswith('take ') and target in a for a in ctx.get('admissible', [])))
    put_ok = bool(target and dest and any(a.startswith('put ') and target in a and dest in a for a in ctx.get('admissible', [])))
    if wrong:
        stage = 'wrong_inventory'
    elif carrying:
        if verb and not nb.get('transformed'):
            stage = 'transform'
        elif put_ok:
            stage = 'put_target'
        else:
            stage = 'go_destination'
    elif take_ok or nb.get('placed_count', 0) < 2:
        stage = 'take_target'
    else:
        stage = 'find_target'
    nb['stage'] = stage
    nb['target_type'] = target
    nb['destination_type'] = dest
    nb['task_type'] = tt
    nb['required_verb'] = verb
    return None

