def hook(ctx, nb):
    stage = nb.get('stage', '')
    target = nb.get('target_type') or 'target object'
    dest = nb.get('destination_type') or 'destination'
    verb = nb.get('required_verb') or ''
    tt = nb.get('task_type') or ''
    msg = ''
    if stage == 'wrong_inventory':
        msg = 'Inventory does not match the requested ' + target + '. Do not place it at the destination; recover by setting it aside if needed and searching for the correct object type.'
    elif stage == 'take_target':
        msg = 'A requested ' + target + ' is available. Take one now instead of continuing to search or inspect unrelated objects.'
    elif stage == 'transform':
        place = 'fridge' if verb == 'cool' else ('microwave' if verb == 'heat' else 'sinkbasin')
        msg = 'You are carrying the ' + target + '. Before placing it, ' + verb + ' it using the ' + place + ' until the transform action is available.'
    elif stage == 'go_destination':
        msg = 'Carry the ' + target + ' to a ' + dest + ' and use the put action there; do not put it on other surfaces.'
    elif stage == 'put_target':
        msg = 'You are at the correct ' + dest + ' with the ' + target + '. Use the admissible put action for that destination now.'
    elif stage == 'find_target' and 'two' in tt and nb.get('placed_count', 0) > 0:
        msg = 'One ' + target + ' is already placed. Leave it there, find another ' + target + ', and use the same ' + dest + ' destination.'
    if not msg:
        return None
    key = stage + ':' + msg[:60]
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}

