def hook(ctx, nb):
    target = nb.get('target_type') or text(getv(ctx, 'task.target_type', ''))
    dest = nb.get('destination_type') or text(getv(ctx, 'task.destination_type', ''))
    tt = nb.get('task_type') or text(getv(ctx, 'task.task_type', ''))
    act = text(getv(ctx, 'action.final_action', getv(ctx, 'action.normalized', getv(ctx, 'action.raw', ''))))
    if not act or not target:
        return None
    if act.startswith('put ') and dest and dest not in act:
        return {'kind': 'block_and_prompt', 'message': 'This is not the requested destination type. Carry the ' + target + ' to a ' + dest + ' and put it there.'}
    if act.startswith('take ') and dest and dest in act and nb.get('placed_count', 0) > 0 and 'two' not in tt:
        return {'kind': 'block_and_prompt', 'message': 'Do not take back a target after placing it at the destination. Continue with any remaining required target instead.'}
    return None
